INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q4551438', '1641 Caracas earthquake', 'The 1641 Caracas earthquake took place in Venezuela on 11 June 1641. It is often known as the San Bernabé earthquake because 11 June is the feast day of Barnabas in the Catholic calendar.', 1641, 6, 11, NULL, NULL, NULL, 'day', '11 June 1641', 34, 'https://en.wikipedia.org/wiki/1641_Caracas_earthquake'),
  ('Q8953', 'Independence of Venezuela', 'The Venezuelan Independence was the juridical-political process that put an end to the ties between the Captaincy General of Venezuela and the Spanish Empire. It also implied the replacement of the absolute monarchy by the republic as the form of government in Venezuela.', 1810, NULL, NULL, 1823, NULL, NULL, 'year', '1810–1823', 37, 'https://en.wikipedia.org/wiki/Venezuelan_independence'),
  ('Q3458386', 'revolution of April 19, 1810', 'The Revolution of April 19, 1810, was an insurrection in Caracas on April 19, 1810, that deposed Vicente Emparan, captain general of Venezuela, and founded the Supreme Junta of Caracas, Venezuela''s first form of self-government. It is conventionally noted as the beginning of the country''s struggle for independence.', 1810, 4, 19, NULL, NULL, NULL, 'day', '19 April 1810', 30, 'https://en.wikipedia.org/wiki/Revolution_of_April_19%2C_1810'),
  ('Q3382350', 'Venezuela Declaration of Independence', 'The Venezuelan Declaration of Independence (Spanish: Acta de la Declaración de Independencia de Venezuela) is a document drafted and adopted by Venezuela on July 5, 1811, through which Venezuelans made the decision to separate from the Spanish Crown in order to establish a new nation based on the premises of equality of individuals, abolition of censorship and dedication to freedom of expression. These principles were enshrined as a constitutional principle for the new nation and were radically opposed to the political, cultural, and social practices that had existed during three hundred…', 1811, 7, 5, NULL, NULL, NULL, 'day', '5 July 1811', 53, 'https://en.wikipedia.org/wiki/Venezuelan_Declaration_of_Independence'),
  ('Q3646645', '1812 Caracas earthquake', 'The 1812 Caracas earthquake took place in Venezuela on March 26 (on Maundy Thursday) at 4:37 p.m. It measured M 7.7.', 1812, 3, 26, NULL, NULL, NULL, 'day', '26 March 1812', 45, 'https://en.wikipedia.org/wiki/1812_Caracas_earthquake'),
  ('Q8940', 'Admirable Campaign', 'The Admirable Campaign (Spanish: Campaña Admirable) was a military expedition conducted by the United Provinces of New Granada and allied venezuelan republican forces against spanish royalist control in western and central Venezuela between 14 of May and 6 of August 1813, during the Spanish American wars of Independence, Colombian war of Independence and Venezuelan war of Independence. The campaign was led by Simón Bolívar, a venezuelan-born officer serving as brigadier in the New Granadan army, with military and logistical support from the United Provinces of New Granada and the Free and…', 1813, 6, 24, NULL, NULL, NULL, 'day', '24 June 1813', 45, 'https://en.wikipedia.org/wiki/Admirable_Campaign'),
  ('Q8951', 'Third Republic of Venezuela', 'The Third Republic of Venezuela (Spanish: Tercera República de Venezuela) was the reestablished Republic of Venezuela declared by Simón Bolívar in the year 1817, during the Venezuelan War of Independence.', 1817, NULL, NULL, 1821, NULL, NULL, 'year', '1817–1821', 47, 'https://en.wikipedia.org/wiki/Third_Republic_of_Venezuela'),
  ('Q388210', 'Battle of Carabobo', 'The Second Battle of Carabobo (Spanish: Batalla de Carabobo), on 24 June 1821, was fought between independence fighters, led by Venezuelan General Simón Bolívar, and the Royalist forces, led by Spanish Field Marshal Miguel de la Torre. Bolívar''s decisive victory at Carabobo led to the independence of Venezuela and establishment of the Republic of Gran Colombia.', 1821, 6, 24, NULL, NULL, NULL, 'day', '24 June 1821', 56, 'https://en.wikipedia.org/wiki/Battle_of_Carabobo'),
  ('Q2890925', 'Naval Battle of Lake Maracaibo', 'The Battle of Lake Maracaibo also known as the "Naval Battle of the Lake" was fought on 24 July 1823 on Venezuela''s Lake Maracaibo between fleets under the commands of Republican Admiral José Prudencio Padilla and royalist Captain Ángel Laborde. The engagement was won by the Republican forces, and was the last battle of the Venezuelan War of Independence and the larger Spanish American wars of independence.', 1823, 7, 24, NULL, NULL, NULL, 'day', '24 July 1823', 41, 'https://en.wikipedia.org/wiki/Battle_of_Lake_Maracaibo'),
  ('Q127831205', 'Fourth Republic of Venezuela', 'The Republic of Venezuela was a democratic bipartidist republic first established in 1953, and replaced in 1999 by the Bolivarian Republic of Venezuela. Venezuela was ruled by a military dictatorship from 1948 to 1958.', 1830, NULL, NULL, 1999, NULL, NULL, 'year', '1830–1999', 26, 'https://en.wikipedia.org/wiki/Fourth_Republic_of_Venezuela'),
  ('Q6107209', 'Revolution of the Reforms', 'The Revolution of the Reforms was a military movement in Venezuela between 7 June 1835, and 1 March 1836, against the government of José María Vargas, the conservative Congress, and the influence of José Antonio Páez. It was led by outstanding independence heroes such as Santiago Mariño, Diego Ibarra, Pedro Briceño Méndez, José Laurencio Silva, José María Melo, Blas Bruzual, Luis Perú de Lacroix, Pedro Carujo, José Tadeo Monagas, Renato Beluche, Andrés Level de Goda, and Estanislao Rendon.', 1835, 6, 7, 1836, 3, 1, 'day', '7 June 1835 – 1 March 1836', 30, 'https://en.wikipedia.org/wiki/Revolution_of_the_Reforms'),
  ('Q5918523', 'Peasant insurrection of 1846', 'The Venezuelan peasant insurrection of 1846 was a popular and social rebellion that broke out in various agricultural areas of Venezuela in September 1846 and lasted until May 1847. The rebellion was suppressed by the Conservative army.', 1846, 9, 1, 1847, 5, 25, 'day', '1 September 1846 – 25 May 1847', 26, 'https://en.wikipedia.org/wiki/1846_Venezuelan_peasant_insurrection'),
  ('Q5484545', 'March Revolution', 'The March Revolution was a military uprising that took place in Venezuela in March 1858. It was the first armed rebellion that managed to overthrow a government in Venezuelan history.', 1858, 3, 15, 1858, 3, 15, 'day', '15 March 1858', 26, 'https://en.wikipedia.org/wiki/March_Revolution_(Venezuela)'),
  ('Q6151933', 'Treaty of Coche', 'The Treaty of Coche was an agreement that formally established the end of the Federal War in Venezuela. The name of the treaty originates from the fact that it was made at the estate of Coche, in that period very close to Caracas, and today part of the Parish of Coche in Caracas.', 1863, 4, 23, NULL, NULL, NULL, 'day', '23 April 1863', 26, 'https://en.wikipedia.org/wiki/Treaty_of_Coche'),
  ('Q3510584', '1875 Cúcuta earthquake', 'The 1875 Cúcuta earthquake (also known as earthquake of the Andes) occurred on 18 May at 11:15 AM. It completely demolished Cúcuta, Villa del Rosario (Colombia), San Antonio del Tachira and Capacho (Venezuela). The earthquake killed many Venezuelans in San Cristóbal, La Mulata, Rubio, Michelena, La Grita, Colón, amongst others, and was felt in both Bogotá and Caracas.', 1875, 5, 18, NULL, NULL, NULL, 'day', '18 May 1875', 37, 'https://en.wikipedia.org/wiki/1875_C%C3%BAcuta_earthquake'),
  ('Q3727804', 'Restorative Liberal Revolution', 'The Restorative Liberal Revolution, also known as the Invasion of the 60 due to the number of men with whom the movement began, was an expedition of Venezuelans exiled in Colombia under the command of Cipriano Castro that began on 23 May 1899, with the purpose of overthrowing the government of Venezuelan President Ignacio Andrade.', 1899, NULL, NULL, 1899, 10, 23, 'year', '1899', 37, 'https://en.wikipedia.org/wiki/Restorative_Liberal_Revolution'),
  ('Q116392571', 'History of Venezuela (1908–1958)', 'Between 1908 and 1958, the Republic of Venezuela saw several changes in leadership, including a coup d''état in 1948.', 1899, 10, 23, 1945, 10, 18, 'day', '23 October 1899 – 18 October 1945', 26, 'https://en.wikipedia.org/wiki/History_of_Venezuela_(1908%E2%80%931958)'),
  ('Q123691912', 'Paris Arbitral Award', 'The Paris Arbitral Award is an arbitral award issued on 3 October 1899 by an arbitral tribunal convened in Paris, created two years earlier as established in the Arbitral Treaty of Washington D. C. on 2 February 1897, in which the United States (representing Venezuela) on the one hand and the United Kingdom (as owner of the colony of British Guiana, currently Guyana) on the other, had agreed to submit to international arbitration the dispute over the border to the west of the British colony and the east of independent Venezuela, as a mechanism for an amicable solution to the territorial…', 1899, 10, 3, NULL, NULL, NULL, 'day', '3 October 1899', 34, 'https://en.wikipedia.org/wiki/Paris_Arbitral_Award'),
  ('Q5873773', '1900 San Narciso earthquake', 'An earthquake occurred in Venezuela on 29 October 1900 (feast of Saint Narcissus of Girona) between 4:30 and 4:45 am local time. Its epicenter was off Miranda State or near the Venezuelan capital Caracas, in the Cariaco Basin.', 1900, 10, 29, NULL, NULL, NULL, 'day', '29 October 1900', 37, 'https://en.wikipedia.org/wiki/1900_San_Narciso_earthquake'),
  ('Q5882499', '1908 Venezuelan coup d''etat', 'During the 1908 Venezuelan coup d''état, General Juan Vicente Gómez took power on 19 December during the absence of President Cipriano Castro. He ruled as a dictator until his death in 1935, either directly by having himself elected by Congress or indirectly through civilian puppet governments that obeyed him.', 1908, 12, 19, 1908, NULL, NULL, 'day', '1908', 26, 'https://en.wikipedia.org/wiki/1908_Venezuelan_coup_d''%C3%A9tat'),
  ('Q3536710', 'Boundary Treaty of 1941 between Colombia and Venezuela', 'The Colombia–Venezuela Boundary Treaty of 1941, officially the Border Demarcation Agreement and Navigation of the Common Rivers between Colombia and Venezuela, and unofficially the López de Mesa-Gil Borges Treaty, was an agreement signed between the governments of Colombia and Venezuela on the land border limits on April 5, 1941, in Colombian city of Villa del Rosario, Norte de Santander, by the Ministers of Foreign Relations of Venezuela, Esteban Gil Borges, and Colombia, Luis López de Mesa. After almost 60 years of negotiations on the demarcation of the Venezuelan–Colombian border…', 1941, 4, 5, NULL, NULL, NULL, 'day', '5 April 1941', 34, 'https://en.wikipedia.org/wiki/Venezuela%E2%80%93Colombia_Boundary_Treaty_of_1941'),
  ('Q4565608', '1945 Venezuelan coup d''état', 'The 1945 Venezuelan coup d''état took place on 18 October 1945, when the president Isaías Medina Angarita was overthrown by a combination of a military rebellion and a popular movement led by Democratic Action. The Medina government discovered the conspiracy by the military to overthrow Medina and arrested Marcos Pérez Jiménez.', 1945, 10, 18, 1945, 10, NULL, 'day', '18 October 1945 – October 1945', 41, 'https://en.wikipedia.org/wiki/1945_Venezuelan_coup_d''%C3%A9tat'),
  ('Q4566363', '1948 Venezuelan coup d''état', 'The 1948 Venezuelan coup d''état took place on 24 November 1948, when Carlos Delgado Chalbaud, Marcos Pérez Jiménez and Luis Felipe Llovera Páez overthrew the elected president, Rómulo Gallegos, who had been elected in the 1947 Venezuelan general election (generally believed to be the country''s first honest election) and had taken office in February 1948. Chalbaud had been Gallegos'' minister of defense.', 1948, 11, 24, 1948, 11, NULL, 'day', '24 November 1948 – November 1948', 34, 'https://en.wikipedia.org/wiki/1948_Venezuelan_coup_d''%C3%A9tat'),
  ('Q3798246', '1958 Venezuelan coup d''état', 'The 1958 Venezuelan coup d''état took place on 23 January 1958, when the dictator Marcos Pérez Jiménez was overthrown. A transition government under first Adm.', 1958, 1, 23, 1958, 1, NULL, 'day', '23 January 1958 – January 1958', 47, 'https://en.wikipedia.org/wiki/1958_Venezuelan_coup_d''%C3%A9tat'),
  ('Q51554154', 'El Barcelonazo', 'El Barcelonazo was an attempted coup d''état against President Rómulo Betancourt''s government that occurred in the Pedro María Freites Barracks in the city of Barcelona, Anzoátegui State on 26 June 1961.', 1961, 6, 26, 1961, NULL, NULL, 'day', '1961', 26, 'https://en.wikipedia.org/wiki/El_Barcelonazo'),
  ('Q5350953', 'El Carupanazo', 'El Carupanazo was a short-lived military rebellion against the government of Rómulo Betancourt, in which rebel military officers commanding the Third Marine Infantry Battalion and the 77th National Guard Detachment took over the city of Carúpano in May 1962. The rebellion was followed a month later by another in Puerto Cabello, El Porteñazo.', 1962, 5, 4, 1962, NULL, NULL, 'day', '1962', 30, 'https://en.wikipedia.org/wiki/El_Carupanazo'),
  ('Q5351866', 'El Porteñazo', 'El Porteñazo (2 June 1962 – 6 June 1962) was a short-lived Communist military rebellion against the government of Rómulo Betancourt in Venezuela, in which rebels attempted to take over the city of Puerto Cabello, located ~75 miles (121 km) West of the capital Caracas. The rebellion was on a substantially larger scale than that of El Carupanazo a month earlier.', 1962, 6, 6, 1962, 6, 6, 'day', '6 June 1962', 34, 'https://en.wikipedia.org/wiki/El_Porte%C3%B1azo'),
  ('Q8187829', 'Geneva Agreement (1966)', 'The Agreement to Resolve the Controversy between Venezuela and the United Kingdom of Great Britain and Northern Ireland over the Frontier between Venezuela and British Guiana, better known as the Geneva Agreement, is a treaty between Venezuela and the United Kingdom, along with its colony of British Guiana (which would soon receive its independence), that was signed in Geneva, Switzerland, on 17 February 1966. The treaty outlines the steps taken to resolve the controversy between Venezuela and the United Kingdom, arising from Venezuela''s contention to the UN in 1962 that the 1899…', 1966, 2, 17, NULL, NULL, NULL, 'day', '17 February 1966', 37, 'https://en.wikipedia.org/wiki/Geneva_Agreement_(1966)'),
  ('Q26293', '1967 Caracas earthquake', 'The 1967 Caracas earthquake occurred in Venezuela on 29 July at 8:00 p.m (UTC−04:00), with its epicenter being 20 km (12 mi) from the Venezuelan capital Caracas. It lasted 35 seconds and heavily affected areas such as Altamira, Los Palos Grandes, and Litoral Central, and it was recorded at 6.6 on the moment magnitude scale.', 1967, 7, 30, NULL, NULL, NULL, 'day', '30 July 1967', 43, 'https://en.wikipedia.org/wiki/1967_Caracas_earthquake'),
  ('Q2254919', 'Pan Am Flight 217', 'Pan Am Flight 217 was a Boeing 707 that crashed near Caracas, Venezuela while on a flight from New York City on December 12, 1968. Though pilot error was to blame, the National Transportation Safety Board concluded the probable cause was undetermined.', 1968, 12, 12, NULL, NULL, NULL, 'day', '12 December 1968', 47, 'https://en.wikipedia.org/wiki/Pan_Am_Flight_217'),
  ('Q2254515', 'Viasa Flight 742', 'Viasa Flight 742 was an international, scheduled passenger flight from Caracas, Venezuela to Miami International Airport, United States with an intermediate stopover in Maracaibo, Venezuela that crashed on 16 March 1969. After taking off on the Maracaibo to Miami leg, the McDonnell Douglas DC-9-32 hit a series of power lines before crashing into the La Trinidad section of Maracaibo.', 1969, 3, 16, NULL, NULL, NULL, 'day', '16 March 1969', 50, 'https://en.wikipedia.org/wiki/Viasa_Flight_742'),
  ('Q3152959', 'Rupununi Uprising', 'The Rupununi uprising was a secessionist insurrection in Guyana that began on 2 January 1969, led by cattle ranchers who sought to control 22,300 square miles (58,000 km2) of land. Occurring less than two years after Guyana''s independence from the United Kingdom, it constituted the country''s earliest and most severe test of statehood and social solidarity.', 1969, 1, 2, NULL, NULL, NULL, 'day', '2 January 1969', 34, 'https://en.wikipedia.org/wiki/Rupununi_uprising'),
  ('Q4697993', 'Air France Flight 212 (1969)', 'Air France Flight 212 was a scheduled passenger flight from Santiago International Airport, was flying to Paris, France via Lima, Peru; Guayaquil, Ecuador; Bogota, Colombia; Caracas, Venezuela; Pointe-à-Pitre, Guadeloupe; and Lisbon, Portugal operated by a Boeing 707, registration F-BHSZ, that crashed on 3 December 1969. All 62 people on board were killed.', 1969, 12, 3, NULL, NULL, NULL, 'day', '3 December 1969', 48, 'https://en.wikipedia.org/wiki/Air_France_Flight_212_(1969)'),
  ('Q6107257', 'Vindicator revolution', 'The Revindicating Revolution was a civil war in Venezuela between supporters and opponents of Antonio Guzmán Blanco, fought between December 1878 and February 1879.', 1978, NULL, NULL, NULL, NULL, NULL, 'year', '1978', 26, 'https://en.wikipedia.org/wiki/Revindicating_Revolution'),
  ('Q5676916', 'Legalist Revolution', 'The Legalist Revolution was a civil war in Venezuela that was caused by the "Continuity movement" of President Raimundo Andueza Palacios who wanted to perpetuate himself in power through a constitutional reform. Although it was constitutionally stipulated that his term would end on 20 February 1892, Andueza planned to reform the Constitution in order to prolong his stay in power for two more years, which is why he was called a Continuationist.', 1982, NULL, NULL, NULL, NULL, NULL, 'year', '1982', 30, 'https://en.wikipedia.org/wiki/Legalist_Revolution'),
  ('Q6784482', 'Massacre of El Amparo', 'The Massacre of El Amparo was a massacre of 14 fishermen which took place near the village of El Amparo, in Venezuela''s western state of Apure, on 29 October 1988.', 1988, 10, 29, 1988, NULL, NULL, 'day', '1988', 34, 'https://en.wikipedia.org/wiki/Massacre_of_El_Amparo'),
  ('Q1035320', 'Caracazo', 'The Caracazo is the name given to the wave of protests, riots, and looting that started on 27 February 1989 in the Venezuelan city of Guarenas, spreading to Caracas and surrounding towns following austerity measures from President Carlos Andrés Pérez. Weeklong clashes resulted in numerous deaths, with estimates ranging from hundreds to thousands, attributed largely to security forces and military involvement, according to various reports.', 1989, 2, 27, 1989, NULL, NULL, 'day', '1989', 52, 'https://en.wikipedia.org/wiki/Caracazo'),
  ('Q2835945', '1997 Cariaco earthquake', 'The 1997 Cariaco earthquake occurred on July 9 at 15:24:14 local time with a moment magnitude of 6.9 and a maximum Mercalli intensity of VIII (Severe). With its epicenter along the El Pilar Fault near Cariaco, Venezuela, at least 81 people were killed and over 500 were injured.', 1997, 7, 9, NULL, NULL, NULL, 'day', '9 July 1997', 34, 'https://en.wikipedia.org/wiki/1997_Cariaco_earthquake'),
  ('Q891367', 'Bolivarian Revolution', 'The Bolivarian Revolution (Spanish: Revolución bolivariana) is a social revolution and ongoing political process in Venezuela that was started by Venezuelan President Hugo Chávez, the founder of the Fifth Republic Movement (MVR) and later the United Socialist Party of Venezuela (PSUV), and his successors Nicolás Maduro and Delcy Rodríguez. The Bolivarian Revolution is named after Simón Bolívar, an early 19th-century Venezuelan revolutionary leader, prominent in the Spanish American wars of independence in achieving the independence of most of northern South America from Spanish rule.', 1999, 2, 2, NULL, NULL, NULL, 'day', '2 February 1999', 64, 'https://en.wikipedia.org/wiki/Bolivarian_Revolution'),
  ('Q2506366', 'Vargas tragedy', 'The Vargas tragedy was a natural disaster that occurred in Vargas State (today La Guaira), Venezuela, on 15 December 1999 (over the course of 10 days), when torrential rains caused flash floods and debris flows that killed tens of thousands of people, destroyed thousands of homes, and led to the complete collapse of the state''s infrastructure. According to relief workers, the neighborhood of Los Corales was buried under 3 meters (9.8 ft) of mud and a high percentage of homes were simply swept into the ocean.', 1999, 12, NULL, 1999, 12, 21, 'month', 'December 1999 – 21 December 1999', 56, 'https://en.wikipedia.org/wiki/Vargas_tragedy'),
  ('Q10752019', 'Venezuelan recall referendum', 'The Venezuelan recall referendum of 15 August 2004 was a referendum to determine whether Hugo Chávez, then President of Venezuela, should be recalled from office. The recall referendum was announced on 8 June 2004 by the National Electoral Council (CNE) after the Venezuelan opposition succeeded in collecting the number of signatures required by the 1999 Constitution to effect a recall.', 2004, 8, 15, NULL, NULL, NULL, 'day', '15 August 2004', 39, 'https://en.wikipedia.org/wiki/2004_Venezuelan_recall_referendum'),
  ('Q2320123', 'West Caribbean Airways Flight 708', 'West Caribbean Airways Flight 708 was a charter flight that crashed in northwest Venezuela in the early hours of 16 August 2005, killing all 160 passengers and crew on board. The plane, a McDonnell Douglas MD-82, registration HK-4374X, was en route from Tocumen International Airport (PTY) in Panama City, Panama, to Martinique Aimé Césaire International Airport in Fort-de-France, Martinique.', 2005, 8, 16, NULL, NULL, NULL, 'day', '16 August 2005', 61, 'https://en.wikipedia.org/wiki/West_Caribbean_Airways_Flight_708'),
  ('Q3087193', 'Santa Bárbara Airlines Flight 518', 'Santa Bárbara Airlines Flight 518 was an ATR 42–300 twin-turboprop aircraft, registration YV1449, operating as a scheduled domestic flight from Mérida, Venezuela, to Caracas that crashed into the side of a mountain on 21 February 2008, shortly after take-off. There were 43 passengers on board, with a crew consisting of two pilots and a flight attendant.', 2008, 2, 21, NULL, NULL, NULL, 'day', '21 February 2008', 51, 'https://en.wikipedia.org/wiki/Santa_B%C3%A1rbara_Airlines_Flight_518'),
  ('Q5166546', 'Conviasa Flight 2350', 'On 13 September 2010, Conviasa Flight 2350, an ATR 42 on a domestic passenger service from Porlamar to Ciudad Guayana, Venezuela, crashed shortly before landing, killing 17 of the 51 people on board; 34 others were injured. The aircraft, a twin-turboprop ATR 42-320, went down in an industrial area after the crew reported control problems.', 2010, 9, 13, NULL, NULL, NULL, 'day', '13 September 2010', 45, 'https://en.wikipedia.org/wiki/Conviasa_Flight_2350'),
  ('Q15729130', 'protests against Nicolás Maduro', 'In 2013, a series of protests, political demonstrations, and civil insurrection began in Venezuela due to the country''s high levels of urban violence, inflation, and chronic shortages of basic goods and services. Explanations for these worsening conditions vary, with analysis blaming strict price controls, alongside long-term, widespread political corruption resulting in the under-funding of basic government services.', 2014, NULL, NULL, 2026, 1, 3, 'year', '2014 – 3 January 2026', 56, 'https://en.wikipedia.org/wiki/Protests_against_Nicol%C3%A1s_Maduro_and_Delcy_Rodr%C3%ADguez'),
  ('Q36015843', '2014 Venezuelan protests', 'In 2014, a series of protests, political demonstrations, and civil insurrection began in Venezuela due to the country''s high levels of urban violence, inflation, and chronic shortages of basic goods attributed to economic policies such as strict price controls. Mass protesting began in earnest in February following the attempted rape of a student on a university campus in San Cristóbal.', 2014, 2, 12, 2014, 5, NULL, 'day', '12 February 2014 – May 2014', 43, 'https://en.wikipedia.org/wiki/2014_Venezuelan_protests'),
  ('Q29548589', 'Mother of All Marches', 'The Mother of All Marches (Spanish: La madre de todas las marchas), also known as the Mother of All Protests, was a day of protests held on April 19, 2017, in Venezuela against the Chavista government of president Nicolás Maduro. The protests began after the Supreme Tribunal of Justice dissolved the National Assembly and took over its legislative powers March 29, 2017 in what was called a self-coup.', 2017, 4, 19, NULL, NULL, NULL, 'day', '19 April 2017', 43, 'https://en.wikipedia.org/wiki/Mother_of_All_Marches'),
  ('Q29842868', '2017 Venezuelan protests', 'The 2017 Venezuelan protests were a series of protests occurring throughout Venezuela. Protests began in January 2017 after the arrest of multiple opposition leaders and the cancellation of dialogue between the opposition and Nicolás Maduro''s government.', 2017, 3, NULL, 2017, 8, NULL, 'month', 'March 2017 – August 2017', 47, 'https://en.wikipedia.org/wiki/2017_Venezuelan_protests'),
  ('Q35212713', 'Ataque al fuerte de Paramacay', 'The attack on Fort Paramacay (code name Operation David), was a military assault carried out in the morning of Sunday, August 6, 2017, between 3:50 a.m. and 8:00 a.m.', 2017, 8, 6, 2017, 8, 6, 'day', '6 August 2017', 26, 'https://en.wikipedia.org/wiki/Attack_on_Fort_Paramacay'),
  ('Q56224430', '2018 Venezuela earthquake', 'On August 21, 2018, a magnitude 7.3 earthquake struck just off the northern coast of Venezuela, near Cariaco, Sucre. The earthquake, at the time, was thought to be the largest in the country since the 1900 San Narciso earthquake.', 2018, 8, 21, NULL, NULL, NULL, 'day', '21 August 2018', 39, 'https://en.wikipedia.org/wiki/August_2018_Venezuela_earthquake'),
  ('Q66474138', 'Catatumbo campaign', 'The Catatumbo campaign has been an ongoing period of strategic violence between militia faction groups in the Catatumbo region of Colombia and Venezuela since January 2018. It is an extension of the war on drugs and developed after the Colombian peace process of 2016.', 2018, 1, NULL, NULL, NULL, NULL, 'month', 'January 2018', 30, 'https://en.wikipedia.org/wiki/Catatumbo_campaign'),
  ('Q63395926', '2019 Venezuelan uprising attempt', 'On 30 April 2019, during the Venezuelan presidential crisis, a group of several dozen military personnel and civilians joined Juan Guaidó in his call for the removal of Nicolás Maduro as part of what he labeled "Operation Freedom" (Spanish: Operación Libertad). Reuters reported an "uneasy peace" by the afternoon of 30 April.', 2019, 4, 30, 2019, NULL, NULL, 'day', '2019', 43, 'https://en.wikipedia.org/wiki/2019_Venezuelan_uprising_attempt'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q109783491', '2021 Amazonas earthquake', 'A major earthquake struck northern Peru on November 28, 2021, 5:52 a.m. local time with a magnitude of 7.5 on the moment magnitude scale between the Amazonas and Loreto departments of Peru.', 2021, 11, 28, NULL, NULL, NULL, 'day', '28 November 2021', 43, 'https://en.wikipedia.org/wiki/2021_Northern_Peru_earthquake'),
  ('Q123324182', '2023 Venezuelan referendum', 'A consultative referendum was initiated by the government of Nicolás Maduro regarding Venezuela''s claim over the Essequibo region, referred to by Venezuela as Guayana Esequiba, a territory disputed with, and controlled by, neighboring Guyana. The referendum took place on 3 December 2023 in Venezuela.', 2023, 12, 3, NULL, NULL, NULL, 'day', '3 December 2023', 52, 'https://en.wikipedia.org/wiki/2023_Venezuelan_referendum'),
  ('Q128036869', '2024 Venezuelan presidential election protests', 'Protests followed the 2024 Venezuelan presidential election on 28 July, in response to voter fraud and other irregularities during the election cycle, as part of the 2024 Venezuelan political crisis. The election and unrest occurred in the context of the ongoing crisis in Venezuela.', 2024, NULL, NULL, 2024, 12, 1, 'year', '2024', 52, 'https://en.wikipedia.org/wiki/2024_Venezuelan_presidential_election_protests');
